"""Generate the R1 report and manuscript results solely from audited saved outputs."""
from decimal import Decimal
import collections
from run_research_validation import ROOT,OUT,load,save,sha,relative

def f(v):
    if v is None:return '—'
    if isinstance(v,(int,float,Decimal)) or isinstance(v,str) and v.replace('.','',1).replace('-','',1).isdigit():
        return f'{float(v):.6f}'.rstrip('0').rstrip('.')
    return str(v)
def table(headers,rows):
    return '| '+' | '.join(headers)+' |\n| '+' | '.join('---' for _ in headers)+' |\n'+''.join('| '+' | '.join(f(x) for x in row)+' |\n' for row in rows)+'\n'

def write():
    rows=load(OUT/'tables.json');pairs=load(OUT/'pairs.json');validation=load(ROOT/'docs/research-audit/results/validation.json')
    matrix=validation['series'];series=[s for s in matrix if not matrix[s]['supersededBeforeAttempt']]
    current=[r for r in rows if r['series']!='baseline'];complete=[r for r in current if r['status']=='FINISHED']
    components=['servedContacts','usefulSecureTime','controlCpu','managementBytes','newKeys']
    def selected(series,models=None):return [r for r in rows if r['series']==series and (models is None or r['model'] in models)]
    def scores(rs):return [[r['model'],r['rule'],r['horizon'],r['status']]+[r.get(k) for k in components] for r in rs]
    headers=['Model','Rule','H','Execution','Served','Useful s','CPU s','Mgmt B','New keys']
    classification=collections.Counter()
    for p in pairs:
        if p['status']!='COMPARABLE':classification[(p['series'],'incomplete')]+=1;continue
        ds=[Decimal(str(p['deltaMultiMinusNext_'+k]))*(1 if i<2 else -1) for i,k in enumerate(components)]
        d=next((d for d in ds if d),Decimal(0));classification[(p['series'],'Multi wins' if d>0 else 'Multi loses' if d<0 else 'equal')]+=1
    issues=[
        ('Search / scale','PARTIALLY_CLOSED','Journal folding verified against full DFS; fixed-node plans unchanged; no measured speedup. Practical mode and cancellation validated; exact and large continuous execution limits remain.'),
        ('Horizon benefit','PARTIALLY_CLOSED','Matched both-rule X/Y/ISS evidence separates exact and practical. Practical budget can lose the historical X5 benefit; no universal advantage.'),
        ('Disclosure / recovery','PARTIALLY_CLOSED','Registered undetected/delayed/contact/gap cases and four independent milestones; protected management and independent replacement assumptions remain.'),
        ('Channel / forecast errors','PARTIALLY_CLOSED','Actual interruptions, delayed AOS/early LOS/missed contact and partial accounting tested. Explicit reconciliation after uncertain SWITCH/OPEN/REUSE is still absent.'),
        ('Different LEO workloads','PARTIALLY_CLOSED','New public NOAA-19/HST GP snapshots, common geometry and full sequences attempted. Incomplete full runs are not replaced by fragment results.'),
        ('Costs / load','PARTIALLY_CLOSED','Compact registered sensitivity and host primitive measurements; synthetic online costs are not calibrated spacecraft handshakes.'),
        ('Compute deadlines','PARTIALLY_CLOSED','Critical-path delay/fallback mode and deadlines measured separately; distributed deployment/telemetry/command cost not validated.'),
        ('Reproducibility','VERIFIED_CLOSED for saved R1 evidence','Source/build/model/JAR/journal/table hashes, protocols, data snapshots and restore instructions provided. This is a dirty-source snapshot, not a claim of a clean committed release.'),
        ('Related work / article','PARTIALLY_CLOSED','Detke full paper/slides and standards checked; R1 manuscript/figures compiled separately. FHAP primary full text and detailed LK-AKA access remain open.'),
        ('Historical 3361 s stall','NOT_REPRODUCED','No cause assigned to GC, solver or Windows software. Bounded cancellation and external watchdog are tested separately.')]
    text='# R1 research validation results\n\n'
    text+='Generated from the saved audited R1 outputs. Historical results are preserved and are not relabeled as new experiments. This stage implements and evaluates changes; it does not establish mission readiness or universal Multi superiority.\n\n'
    text+='## 1. Starting state and issue dispositions\n\nBase commit `3621333d8093b4cb0c232c7db9164c66e273053c`; the initial dirty tree is frozen in [environment.json](target/research-validation/environment.json). The latest supplied PDF differs from the available TeX source; the new manuscript is an explicitly identified R1 revision. The historical synthesis recount remains **63 FINISHED, 20 SEARCH_INCOMPLETE, 1 controller-limited; 21/42 complete pairs**. Three extra historical technical attempts are separate.\n\n'
    text+=table(['Issue','Status','Evidence / remaining condition'],issues)
    text+='Detailed original claims, implementation paths and closure criteria: [issue matrix](docs/research-audit/issue-matrix.md). NOT_REPRODUCED does not mean fixed. Broad issues are not closed by adding a discussion caveat.\n\n'
    text+='## 2. Actual implementation changes\n\n'
    text+='- `PlanningJournalSummary`, `ExactHorizonPlanner`, `PlanningOptimisticBound`, `PlanningStateKey`: share a derived immutable per-snapshot journal fold. Bounds, candidate space, five priorities and complete plan comparator remain unchanged.\n'
    text+='- `BudgetedHorizonPolicy`: separate local-budget incumbent/fallback mode; INCOMPLETE stays in the ledger. Practical-v2 feasible suffix reuse requires full observation equality after one completed frame and current candidate membership. It grants no optimality certificate.\n'
    text+='- `PlanningLatencyController`: advance actual model events while a decision is unavailable, revalidate intent, wait after deadline miss. Existing offline exact controller remains available.\n'
    text+='- `ChannelInterruption`, `SimulationScenario`, `SimulationEngine`, `PlanningObservation`, `ExecutionSnapshot`, `SimulationEvent`: actual availability events separate from predicted contacts, committed work interruption and checkpoint restoration.\n'
    text+='- `LifecycleTransitions.recordAbortedTransmission`: a committed aborted frame consumes its nonce while adding no delivered frame or successful-contact history. This is required when the same key can resume after an outage; it does not establish a historical exploit for irreversibly retired keys.\n'
    text+='- `ResearchValidationMain`, `HostCryptoMicrobenchmark`, Python registration/audit/plot/report scripts; R1 recovery replay accounts for aborted nonces and observed channel availability. Historical replay defaults remain unchanged.\n\n'
    text+='[Execution, deployment and cost contract](docs/research-audit/execution-and-costs.md), [channel semantics](docs/research-audit/channel-model.md), [search correctness/profile](docs/research-audit/search-diagnosis.md).\n\n'
    text+='## 3. Validation, tools and reproduction\n\nJava 21.0.10, Maven 3.9.9 wrapper, Windows, Ryzen 7 5800HS, 16 logical CPUs and 16,541,487,104 bytes RAM. All experiment JVMs ran serially with `-Xmx1024m`. Host timings are measurements of this machine, not onboard benchmarks.\n\n'
    text+='Fresh isolated candidate tests: **423 passed, 0 failures/errors** after repairing a new test fixture and restoring required local data. After practical-v2, **74 focused Java tests passed**, including 12 componentwise quality rows; these overlap the 423 and must not be added. **10 focused Java tests passed** after the export-only repair. **67 Python tests passed**, including 17 R1 journal corruption/regression checks. [Test logs and manifests](target/research-validation/) retain failed intermediate builds too.\n\n'
    text+='The first baseline build had 22 errors: missing local data fixtures and blocked loopback import tests. Original-source fixture tests passed after data restoration; loopback tests passed in the subsequent permitted run. The first new quality-test attempt exhausted a 250000-node full-DFS root before the existing warmup. Its failure log is retained. The follow-up uses the two already defined warmed witness states, with unchanged budgets; it is not a successful full-root oracle. The 12 warmed comparisons match all five components, not a general approximation bound.\n\n'
    text+='Atomic checkpoint tests exercise bounded transient/permanent rename failures, last-good preservation and restoration. A separate watchdog probe reaped a silent process in about 2.031 s under a 2 s limit. Every available saved checkpoint is compared with the exported state and journal; Java tests separately execute restoration. Rename timing/retries, search phase CPU/wall/GC and sampled heap are recorded, with unavailable values left absent/null.\n\n'
    text+='```powershell\n$env:JAVA_HOME = "C:\\Program Files\\Java\\jdk-21.0.10"\n$env:PATH = "$env:JAVA_HOME\\bin;$env:PATH"\n.\\mvnw.cmd -B -ntp test\npython -X utf8 -m unittest discover -s scripts -p "test_*.py"\npython -X utf8 scripts/analyze_research_validation.py\npython -X utf8 scripts/plot_research_validation.py\n```\n\n'
    text+='For faithful saved-version execution use the frozen JAR and model from the series protocol, not an arbitrary current checkout. The scripts refuse existing attempts. See [reproduction instructions](docs/research-audit/reproduction.md) for source snapshots, data restore and a new output path. Maven tests need the declared local orbit/station/earth data; a clean checkout without restoration is insufficient.\n\n'
    text+='## 4. Registered matrix and completion\n\n'
    text+=table(['Series','Planned','Attempted','FINISHED','Search incomplete','Controller limit','Other failed','Not run'],[
        [s,matrix[s]['planned'],matrix[s]['attempted'],matrix[s]['statuses'].get('FINISHED',0),matrix[s]['statuses'].get('SEARCH_INCOMPLETE',0),matrix[s]['statuses'].get('CONTROLLER_TIME_LIMIT',0),sum(n for k,n in matrix[s]['statuses'].items() if k not in ['FINISHED','SEARCH_INCOMPLETE','CONTROLLER_TIME_LIMIT']),matrix[s]['notRun']] for s in series])
    text+=f"Excluding the 12 pre-change baseline attempts: **{len(current)} attempted, {len(complete)} FINISHED**. Matched R1 horizon comparisons: **{validation['completedPairs']}/{validation['allPairs']} complete pairs**; unmatched H3 and Fixed/PerContact controls are not counted as pairs.\n\n"
    text+='Six original practical-series registrations were superseded **before any attempts** by practical-v2 registrations with identical cases/budgets and a new binary. They remain saved; their planned cells are not counted twice. No limit was increased to obtain COMPLETE. One deterministic configuration is an experimental unit; repeated builds/probes are not independent service observations.\n\n'
    text+=table(['Series','Multi wins (five-criterion order)','Equal','Multi loses','Incomplete pair'],[[s,*[classification[(s,k)] for k in ['Multi wins','equal','Multi loses','incomplete']]] for s in sorted(set(p['series'] for p in pairs))])
    text+='Exact: 2,000,000 nodes / 30 s per decision, 60 s controller, 90 s process. Practical: 5000 nodes / 1 s per decision, 20 s controller, 35 s process. Practical FINISHED describes a complete physical execution, not all searches being COMPLETE. Missing final quality is not zero. All cases, costs, reasons and per-search diagnostics: [runs.csv](docs/research-audit/results/runs.csv), [pairs.csv](docs/research-audit/results/pairs.csv), [matrix.json](docs/research-audit/results/matrix.json).\n\n'
    text+='## 5. Horizon, rule and cost results\n\n'
    text+=table(headers,scores(selected('exact',['X3','X5','X9','Y'])))
    text+='The exact X5 CONTINUE_WAIT result retains the earlier conditional short-return mechanism when that execution finishes. CANONICAL incomplete cells cannot be inferred from it. The autonomous model charges only newly executed preparation; its Next CPU is 0.12 s, distinct from the old 0.32 s shared-preparation fixture.\n\n'
    text+=table(headers,scores(selected('practical-v2',['X3','X5','X9','Y','demand-none','demand-late-detected'])))
    text+='Under the registered small practical budget, X5 Multi loses the earlier third-contact advantage and equals Next. In the high-demand no-attack fragment, CANONICAL can keep service but spend extra CPU/bytes/keys; CONTINUE_WAIT may lose service. These are observed budgeted-controller outcomes, not exact-optimum losses or a changed objective. A larger horizon can worsen the feasible plan found within a fixed search budget.\n\n'
    text+='Two finite-offer CANONICAL cases retain a practical horizon benefit: X-light (400 B/direction/contact) and X-medium (1600 B/direction/contact) each gain one served contact with Multi. The respective useful-time gains are 2 and 4 s. Both cost an extra 0.71 s operation CPU, 1080 management bytes and two new keys. This is not evidence for CONTINUE_WAIT on these unrun factor cells or an optimum guarantee for the bounded solver.\n\n'
    text+='Cost/load sensitivities vary one axis at a time: operation duration, cryptoperiod, material age, reuse gap, offer, minimum, frame size and H. Numeric ranges and snapshots are in protocols, with incomplete cells retained. Increasing frame bytes without changing frame duration changes modeled rate as well as quantization; this is not an isolated wire-framing efficiency claim. Initial key notAfter values remain fixed in cryptoperiod sensitivity.\n\n'
    text+='The effective deadline is the minimum of stored notAfter, activation + cryptoperiod and creation + maximum age. Thus CP=90 s tightens the old A pair deadline to t=10 even though stored notAfter stays t=70. In its Next journal PREPARE completes at t=10, INSTALL at 14, SWITCH at 15 and OPEN at 16; both horizons then serve three contacts. Renewal needed within the current contact removes the need for extra visibility in this case. CP=240 cannot extend the stored old-key deadline and both practical policies serve two. These two settings do not establish robustness to arbitrary cryptoperiods.\n\n'
    text+='FixedPeriod ranges are T=30/60/90/120 s on X5 and 1800/3600/5400 s on full ISS46. Each runs the same input and constraints as its comparison family; full ISS results are meaningful only if FINISHED.\n\n'
    text+=table(['Model','Policy','T s','Status','Served','Useful s','CPU s','Mgmt B','New keys'],[
        [r['model'],r['mode'],next(c.get('period_s') for c in load(OUT/'controls-v2/protocol.json')['cases'] if c['id']==r['case']),r['status'],*[r.get(k) for k in components]] for r in selected('controls-v2')])
    text+='Host primitive measurements and the fixed-node comparison are in [search-measurements.md](docs/research-audit/search-measurements.md). After the aggregate change, this single diagnostic was about 1.89%/2.47% slower for CANONICAL/CW, with the same 20000-node incumbent plan and score. It provides no measured speedup; the historical 3361 s stall remains unexplained.\n\n'
    text+='FixedPeriod T=90 serves all three X5 contacts (36 s useful, 1.09 s CPU, 1320 management bytes, four new keys); the other tested X periods do not. All four completed ISS46 operational controls serve 46 contacts and provide 920 s useful time. The missing search-policy finals cannot be ranked against them as service losses.\n\n'
    text+=table(['ISS46 rule','H','Contacts started at stop','Search s','Checkpoint s','Searches','Certified suffixes','Feasible suffixes'],[[r['rule'],r['horizon'],r.get('contactsStarted'),r.get('searchSeconds'),r.get('checkpointSeconds'),r.get('searches'),r.get('suffixReuses'),r.get('feasibleSuffixReuses')] for r in selected('practical-v2',['ISS46'])])
    text+=f"Across the saved R1 runs, checkpoint diagnostics record {sum(r.get('checkpointRetries',0) for r in rows)} bounded retries, with no checkpoint process failure. This does not identify the Windows process responsible for a transient denial. The full ISS samples spend about 18.5–19.5 s of their 20 s budget inside searches, versus 0.35–1.10 s in checkpoint writes: repeated decision search, rather than checkpoint time alone, is the measured dominant cost in these cases.\n\n"
    text+='## 6. Disclosure, recovery, actual channel and deadlines\n\n'
    sec=selected('security-v2')
    text+=table(['Case','Rule','H','Status','Confidential served','Confidential B','Historical exposure B','Post-disclosure B','Recovery'],[[r['model'],r['rule'],r['horizon'],r['status'],r.get('confidentialServedContacts'),r.get('confidentialDeliveredBytes'),r.get('decryptableBeforeBytes'),r.get('decryptableAfterBytes'),r.get('recoveryStatus')] for r in sec])
    text+='The external attack remains fixed per pair; actual active keys determine the disclosed IDs. NO_TARGET is retained. Traffic-key disclosure assumes recorded ciphertext, protected management credentials and independent replacement material with no persistent attacker access. Root compromise, active forgery and real RF jamming are not evaluated.\n\n'
    milestones=['spacecraft_notice','independent_pair','independent_sa','independent_frame']
    rec=selected('exact',['ISS5400-p30-detected'])+selected('security-v2',['X-detected2'])
    text+=table(['Model','Rule','H','Status','SC notice s','Activation s','SA open s','First frame s'],[[r['model'],r['rule'],r['horizon'],r['status'],*[r.get(k+'Seconds') if r.get(k+'Status') in ['event','already-ready-at-origin'] and r['status']=='FINISHED' else r.get(k+'Status') for k in milestones]] for r in rec])
    text+='These times originate at GS notice. Pair/SA readiness intervals retain later expiry and closure; first activation is not continuous readiness. Material, notification, contact and offered-data waiting flags can overlap and are not additive. The observed ISS gap between activation and first delivered frame is kept explicit.\n\n'
    text+=table(['Interruption','Rule','H','Status','Served','Useful s','Aborted frames','Failures'],[[r['model'],r['rule'],r['horizon'],r['status'],r.get('servedContacts'),r.get('usefulSecureTime'),r.get('abortedFrames'),r.get('failures')] for r in selected('disruptions-v2')])
    text+='Controlled outages are actual-channel availability interventions, including a possible jamming-induced interruption interpretation, not an RF jammer model. Online work stops, partial cost and uncertainty persist, nonces are not reused, and future actual recovery is hidden from planning. Tests separately interrupt INSTALL, SWITCH, OPEN/REUSE and payload, including missing ACKs and checkpoint boundaries. The small outage matrix is not a stochastic reliability study.\n\n'
    text+=table(['Case','H','Rule','Status','Deadline misses','Served','Useful s'],[[r['case'],r['horizon'],r['rule'],r['status'],r.get('deadlineMisses'),r.get('servedContacts'),r.get('usefulSecureTime')] for r in selected('deadlines-v2')+selected('deadlines-v3')])
    text+='The 50/500 ms delays are synthetic, host-scale zero, with a 250 ms budget. A missed decision waits safely. Search termination, scenario termination, service and deadline compliance are four separate outcomes. The logical ground coordinator is not a completed ground/onboard command implementation. The initial deadlines-v2 attempt failed while serializing an internal CertifiedSearch capability; seven cells were not run under its stop rule. The export-only repair has a separate JAR, 10 passing focused tests and deadlines-v3 registration with unchanged models/limits. This failed technical attempt remains counted in executions but is not duplicated as a selected horizon pair.\n\n'
    text+='At 50 ms, both completed Next runs retain two served contacts but useful time falls from 38 to 31.5 s; both Multi runs stop on the 20 s controller budget. Their raw status is SEARCH_INCOMPLETE and the search ledger explicitly identifies CONTROLLER_TIME_LIMIT. At 500 ms all four runs finish safely with nine deadline misses and no service. The latency adapter does not populate the legacy computation-summary object: its zero defaults are marked unavailable in postprocessing; authoritative elapsed/CPU comes from measurement and per-search ledgers. These are observable adapter/reporting limits, not zero computation.\n\n'
    text+='## 7. Continuous workloads and evidence limits\n\n'
    workloads=['ISS46','ISS44','ISS45','33591-base','20580-base']
    text+=table(['Workload','Contacts','Rule','H','Status','Served','Useful s','Searches','Nodes'],[[r['model'],r['contacts'],r['rule'],r['horizon'],r['status'],r.get('servedContacts'),r.get('usefulSecureTime'),r.get('searches'),r.get('nodes')] for r in selected('practical-v2',workloads)])
    text+='ISS days use the saved suitable-epoch ISS snapshot and retain state across all 46/44/45 contacts. NOAA-19 (98.94 deg inclination) and Hubble (28.47 deg) use freshly acquired GP epochs on October 24 for October 25–26 propagation, within the 72 h acquisition bound. Their base common schedules have 38 and 48 contacts. Other days of ISS are not independent missions. Public stations are a hypothetical authorized cohort, not permission for actual secure uplink. Elevation 20 deg, 16-station cohort and 30 s switching-guard variants are common inputs for both policies. [Source provenance](docs/research-audit/workload-sources.md).\n\n'
    text+='Where a full continuous run remains incomplete, that workload is not validated by its prefix or a successful triple. No completed-fragment result is promoted to a full-mission result. Exact finite-model evidence, host measurements, synthetic interventions and public geometry are distinct evidence classes.\n\n'
    text+='## 8. Article, figures and next substantive step\n\n'
    text+='The separately identified [R1 manuscript](docs/paper-r1/main.tex) retains negative/incomplete results in the main text; [supplement](docs/paper-r1/supplement.tex) holds technical history. The compiled [main PDF](docs/paper-r1/main.pdf) has eight pages and the [supplement PDF](docs/paper-r1/supplement.pdf) has four. All pages and six figures were visually reviewed; no overfull boxes or unresolved references remained. Minor underfull-box/font-configuration warnings are retained in the logs. Compile diagnostics and source/PDF hashes are saved alongside results. Detke et al.\'s full six-page conference paper and eight-page slides were inspected: route/key-scope optimization is close prior work, and temporal key scheduling is explicitly future work. IOTA already includes contact-dependent allowlists/revocation. R1 does not invent MPC, lifecycle states, or contact-aware security. [Primary-source comparison](docs/research-audit/related-work.md).\n\n'
    text+='The [reproduction package](target/research-validation/r1-reproduction.zip) includes frozen sources, four identified JARs, required test/public-input fixtures, registered protocols, all new journals, tables, figures and test evidence. [package.json](target/research-validation/package.json) records its SHA-256 and ZIP integrity; [manifest.json](target/research-validation/manifest.json) maps source/build/result identities. All 4195 protected historical files passed the byte-preservation check.\n\n'
    text+='Figures are generated from saved audited tables, with PDF/SVG/PNG exports and per-figure provenance: [horizon/cost](docs/paper-r1/figures/service_cost_horizon.pdf), [runtime/completion](docs/paper-r1/figures/runtime_completion.pdf), [sensitivity](docs/paper-r1/figures/sensitivity.pdf), [timeline](docs/paper-r1/figures/mechanism_timeline.pdf), [four recovery stages](docs/paper-r1/figures/recovery.pdf), [exposure with separate policy/hatch legends](docs/paper-r1/figures/detected_exposure.pdf).\n\n'
    text+='The next substantive step is to improve or qualify the practical controller on the observed failed full sequences and the measured service losses, using the saved decision observations as small reproducible optimization targets. Any pruning/batching must preserve the full comparator and information boundary against the full-DFS oracle; any heuristic change needs a new identity/protocol and a quality comparison. Do not raise timeouts or change the objective until Multi appears favorable. Mission-calibrated link/management timing and distributed reconciliation remain separate work.\n'
    (ROOT/'RESEARCH_VALIDATION_RESULTS.md').write_text(text,encoding='utf-8')
    # Compact results included by the main manuscript; no invented missing quality values.
    esc=lambda s:str(s).replace('_',r'\_')
    active=[s for s in series if s!='baseline'];lines=[]
    lines.append(r'\subsubsection{Coverage and execution mode}')
    lines.append(f'R1 attempted {len(current)} registered post-change executions; {len(complete)} reached FINISHED. Of {validation["allPairs"]} matched horizon pairs, {validation["completedPairs"]} finished both policies. The 12 pre-change baseline attempts produced 11 FINISHED and one search-incomplete execution and are excluded from these R1 counts.')
    lines.append(r'\begin{table}[t]\centering\caption{R1 execution completion. Search completeness is separate.}\label{tab:r1coverage}\begin{tabular}{lrrr}\toprule Series & Planned & Attempted & Finished\\\midrule')
    for s in active:lines.append(f'{esc(s.replace("-v2",""))} & {matrix[s]["planned"]} & {matrix[s]["attempted"]} & {matrix[s]["statuses"].get("FINISHED",0)}'+r'\\')
    lines.append(r'\bottomrule\end{tabular}\end{table}')
    lines.append(r'\subsubsection{Finite-budget horizon effects}')
    lines.append('The exact series finishes 30 of 40 executions and 10 of 20 pairs. Eight searches stop incomplete and two controllers reach their total budget. The finished exact X/5 CONTINUE\\_WAIT pair retains three versus two served contacts for Multi versus Next, at 37 versus 38 s useful time, 0.83 versus 0.12 s operation CPU, 1240 versus 160 management bytes, and two versus zero new keys. This is the autonomous preparation model, not the older shared-preparation accounting.')
    lines.append('At the practical 5000-node/1-s decision budget, both rules produce only two served contacts for both policies on X/5: the earlier exact benefit is lost. On the high-demand no-attack ISS fragment, CANONICAL serves three contacts for both policies, but Multi spends 0.65 s more operation CPU, 1000 additional management bytes and creates two additional keys. CONTINUE\\_WAIT serves two contacts with Multi versus three with Next (40 versus 410 s useful time). These are feasible bounded-controller outcomes, not a reversal of an exact optimum; additional horizon competes for the same search budget.')
    lines.append('Finite offered demand changes this outcome: at 400 and 1600 bytes per direction/contact, CANONICAL practical Multi gains one served contact, with respectively 2 and 4 s extra useful time. Each gain costs 0.71 s more operation CPU, 1080 additional management bytes and two new keys. Those factor cells do not test the other tie rule. FixedPeriod T=90 s also serves all three X/5 contacts; all tested full-ISS operational controls serve 46 contacts. Full search-policy execution remains incomplete, so no missing final service score is ranked against those controls.')
    lines.append('Tightening cryptoperiod to 90 s forces the old A pair to expire within C1 at t=10; Next activates its replacement at t=15 and both horizons then serve three contacts. This is a case where current-contact renewal makes extra visibility unnecessary. Increasing cryptoperiod to 240 s does not extend a stored earlier notAfter. These specific outcomes do not imply monotonic benefit or arbitrary-cryptoperiod robustness.')
    lines.append(r'\subsubsection{Diagnostics, controls and model boundaries}')
    lines.append('A fixed-root 20000-node diagnostic preserves the entire incumbent plan and all five metrics under both rules, but the aggregate change is 1.89\\% and 2.47\\% slower in these individual profiled runs. No acceleration is claimed. Twelve practical-versus-full-DFS comparisons from two previously established warmed states have zero difference in all objective components; the initial fresh-root oracle exceeded its unchanged node cap. This local agreement supplies no general approximation guarantee.')
    lines.append('The matrix separately retains undetected and delayed disclosures, gap disclosure, four channel interventions, fixed-period controls, and synthetic 50/500 ms decision delays against a 250 ms deadline. Journal-derived recovery distinguishes spacecraft notice, independent activation, SA opening and first delivery. Successful activation does not imply continuous readiness. Full-sequence ISS, NOAA-19 and HST attempts retain incomplete outcomes; they are not replaced with selected triples. Numeric sensitivity and per-case source links are available in the reproduction tables.')
    (ROOT/'docs/paper-r1/r1-results.tex').write_text('\n\n'.join(lines)+'\n',encoding='utf-8')
    save(OUT/'report-inputs.json',{relative(p):sha(p) for p in [OUT/'tables.json',OUT/'pairs.json',ROOT/'docs/research-audit/results/validation.json']})
    print('Report generated',len(current),'post-change attempts',len(complete),'finished')

if __name__=='__main__':write()
